/* Built-in playbook pack. Each step: [what to do, how / what good looks like]. */
const PB_PACK = [
  /* ---------------------------------------------------------------- OSINT */
  {id:"pb-subject-profile", name:"Subject profile (person)", cat:"osint", icon:"user", level:"core", time:"2–6 h",
   desc:"A proportionate, documented open-source profile of a named individual, within an agreed scope and legal basis.", steps:[
    ["Record the tasking, the requester and the lawful basis before collecting anything", "Write down who asked, why, and the legal basis (e.g. GDPR Art. 6 legitimate interests with a short balancing test, a court order, a contract clause). No basis or a personal grudge = stop. Declining is a valid outcome."],
    ["Define the scope: questions to answer, sources allowed, data you will not collect", "List the exact questions (e.g. 'is this the same person as the company director?'). Exclude family members, health, religion, sexuality and other special-category data unless strictly required and lawful."],
    ["Prepare an attributable-safe research environment", "Separate browser profile or VM, research accounts that do not identify you or the client, no logged-in personal accounts. Never interact with the subject, friend/follow, or message them."],
    ["Start a capture log so every finding has a URL, time and screenshot", "Hunchly, or OSINTrix Capture with an archived copy (Wayback Machine Save Page Now, archive.today). A finding you cannot re-show is not evidence."],
    ["Establish identifiers you were given and confirm they belong to the subject", "Full name + date of birth / city / employer combinations. Same-name confusion is the most common profiling error — require two independent matching attributes before linking."],
    ["Search public records relevant to the scope", "Company registers (Companies House officers, OpenCorporates), court listings, professional registers, electoral roll only where lawful in your jurisdiction. Note the date of each record — addresses age fast."],
    ["Review public social media and professional profiles", "Public posts only — no access to private accounts, no pretexting. Record join dates, stated employers and locations; screenshot with the URL visible."],
    ["Pivot carefully on usernames, emails and photos already in scope", "Use the Username, Email and Image provenance playbooks for depth; only follow pivots that answer a scoped question."],
    ["Corroborate each key fact with a second independent source", "Mark each fact Confirmed / Probable / Unverified. Two pages copying the same people-search site are one source, not two."],
    ["Apply data minimisation: remove anything outside scope", "Delete or exclude incidental third-party data (relatives, neighbours, children). Keep only what answers the questions."],
    ["Write the profile with confidence levels and alternative explanations", "State gaps and what would change the assessment. Avoid speculative language about character or intent."],
    ["Set retention and secure storage for the case material", "Agree a deletion date with the requester; restrict access to the case. Record the decision in the case notes."]]},

  {id:"pb-company-dd", name:"Company due diligence", cat:"osint", icon:"building-2", level:"core", time:"2–4 h",
   desc:"Check that a company is real, who owns and runs it, and whether it carries sanctions, legal or reputational risk.", steps:[
    ["Confirm the legal entity: exact registered name, number, jurisdiction and status", "National registers (UK Companies House, SEC EDGAR, state registries) and OpenCorporates. Trading names often differ from the legal entity — match the number, not the name."],
    ["Look up the LEI and parent/child relationships", "GLEIF LEI search shows direct and ultimate parents where reported."],
    ["Identify directors, officers and beneficial owners", "Companies House officers and PSC register; note appointment dates and other directorships. Many directorships at one address can indicate a formation agent or nominee setup."],
    ["Screen the entity, owners and directors against sanctions and PEP lists", "OpenSanctions, OFAC SDN search, UK sanctions list, EU sanctions map. Record name variants and transliterations searched; a non-match on one spelling is not a clearance."],
    ["Check the registered and trading addresses", "Street view and search the address: virtual office, mail-drop or residential addresses with hundreds of companies are a flag, not proof."],
    ["Review filing history and financials", "Late or missing accounts, sudden dormancy, frequent officer changes, recently changed names or a very new company trading at large volumes."],
    ["Search court records and insolvency notices", "PACER / CourtListener (US), The Gazette (UK insolvency notices), local court portals."],
    ["Run adverse media searches in relevant languages", "Name + fraud / lawsuit / sanction / bribery / investigation; include former names and key people. Note source quality."],
    ["Check offshore and leak datasets", "ICIJ Offshore Leaks database. Presence is not wrongdoing — record context."],
    ["Assess the web presence and domain", "Domain age via RDAP, Wayback Machine history, copied text or stock-photo staff, mismatched phone/country. Use the Website attribution playbook if it looks fabricated."],
    ["Summarise risk with a clear rating and the evidence behind it", "Low / Medium / High with each driver cited. List what you could not verify."]]},

  {id:"pb-email-investigation", name:"Email address investigation", cat:"osint", icon:"mail", level:"core", time:"30–90 min",
   desc:"Work out whether an email address is real, what accounts and breaches it is tied to, and who may be behind it.", steps:[
    ["Validate the address format and the domain's mail setup", "Check MX records; a domain with no MX or a disposable-mail provider (e.g. mailinator-style services) changes the picture."],
    ["Identify the provider and whether the domain is custom", "Custom domain → run WHOIS/RDAP, crt.sh and the Domain & infrastructure playbook on it."],
    ["Search the exact address in quotes across search engines and code sites", "Google/Bing/DuckDuckGo, GitHub (commit author emails), paste sites, PGP keyservers such as keys.openpgp.org."],
    ["Check breach exposure", "Have I Been Pwned shows which breaches include the address and their dates — a timeline of when the address existed."],
    ["Check registration on services", "Tools such as Holehe or Epieos test sign-up / reset flows. Some sites may notify the owner — note the risk, and do not trigger password resets."],
    ["Look up a Gravatar / avatar tied to the address", "Gravatar profiles are keyed on a hash of the email; a profile can give a name, photo and linked sites."],
    ["Derive and test the username part", "The local part (before @) is often reused as a handle — hand off to the Username & persona playbook."],
    ["If you have a received message, analyse its headers", "Originating IP, mailer, time zone in Date header, Message-ID domain. Decoder helps with encoded-word subjects and base64 parts."],
    ["Link findings with evidence and confidence", "Each account or name linked to the address needs its source; avoid linking on name similarity alone."],
    ["Record the verdict: real / disposable / spoofed / unknown, and next pivots", "Add the address as an entry with its verdict so it follows into other cases."]]},

  {id:"pb-phone-number", name:"Phone number investigation", cat:"osint", icon:"phone", level:"core", time:"30–60 min",
   desc:"Identify a number's country, type and original carrier, and find where it appears publicly.", steps:[
    ["Normalise the number to E.164 format", "+<country code><number>. Many lookups fail on local formats; keep both versions for searching."],
    ["Parse country, region and line type", "libphonenumber-based tools give mobile / fixed / VoIP / toll-free and the original allocation. Number portability means the current carrier may differ."],
    ["Check for VoIP or virtual-number providers", "Google Voice, TextNow and similar are common in scams; the original range allocation often reveals it."],
    ["Search the number in multiple formats", "With and without country code, spaces, dashes and brackets. Classifieds, business listings, scam-report sites, forum posts."],
    ["Check messaging-app presence only from a research device and within policy", "WhatsApp/Telegram/Signal presence via a sock-puppet contact list can reveal a profile photo or name. Some jurisdictions treat this as processing personal data — confirm scope first."],
    ["Treat caller-ID apps with care", "Apps like Truecaller rely on uploaded contact books; results are crowd-sourced and may be wrong or outdated. Never upload a real contact list."],
    ["Do not call or text the number", "Contact can alert the subject and may breach your rules of engagement."],
    ["Check breach and leak data for the number", "Some breaches (e.g. large social-platform scrapes) included numbers; record breach name and date."],
    ["Record type, confidence and linked identities", "Note what is confirmed (allocation) versus crowd-sourced (names)."]]},

  {id:"pb-account-authenticity", name:"Social account authenticity & bot network", cat:"osint", icon:"bot", level:"advanced", time:"2–4 h",
   desc:"Assess whether an account is genuine, and whether it is part of a coordinated or automated network.", steps:[
    ["Archive the account and a sample of posts before analysis", "Screenshots plus archive.today / Wayback snapshots; accounts get suspended mid-investigation."],
    ["Check account age, name changes and platform transparency data", "Facebook Page Transparency (creation date, name history, manager countries), X 'About this account', YouTube channel About. Recent creation + high volume is a flag."],
    ["Inspect the profile photo", "Reverse-search it (Google Lens, Yandex, TinEye). Stolen photos or AI-generated faces (perfectly centred eyes, warped backgrounds, mismatched earrings) are common in fake networks."],
    ["Analyse posting behaviour", "Posts per day, 24/7 activity, regular intervals, burst timing, ratio of original posts to reposts. Plot posting hours — humans sleep."],
    ["Look for copy-paste and coordinated content", "Search distinctive phrases in quotes; identical text across accounts within minutes is strong evidence of coordination."],
    ["Map the network: who they amplify and who amplifies them", "Shared followers, reply chains, same hashtags at the same times. Graph the accounts in OSINTrix with evidence on each link."],
    ["Check handle patterns and creation clusters", "Name + 8 digits handles, sequential creation dates, the same bio template."],
    ["Use bot-scoring tools only as one input", "Scores are unreliable and platform API changes have limited many tools (e.g. Botometer X is archive-only). Never call an account a bot on a score alone."],
    ["Consider innocent explanations", "Activists, shift workers, scheduling tools and fan accounts can look coordinated. Write the alternatives down."],
    ["Rate confidence per account and for the network", "Separate 'inauthentic' (fake identity), 'automated' and 'coordinated' — they are different findings."],
    ["Report to the platform if policy is breached and record the response", "Platform reporting channels for coordinated inauthentic behaviour; keep your archive in case content is removed."]]},

  {id:"pb-image-provenance", name:"Image provenance & reverse search", cat:"osint", icon:"image", level:"core", time:"30–90 min",
   desc:"Find the earliest source of an image, whether it was altered, and whether it matches the claim made about it.", steps:[
    ["Obtain the highest-quality, earliest copy you can", "Ask the source for the original file. Social platforms recompress and strip metadata."],
    ["Read metadata and Content Credentials", "exiftool or Forensics kit → Image / EXIF. Check C2PA Content Credentials (contentcredentials.org/verify). Missing metadata proves nothing; present metadata can be edited."],
    ["Reverse-search with several engines", "Google Lens, Bing Visual Search, Yandex Images, TinEye (sort by oldest). Engines index differently — use all of them."],
    ["Crop and search distinctive regions", "Faces, signs, logos, landmarks searched separately often find matches that the whole image misses."],
    ["Establish the earliest appearance and its context", "Note the first upload date, uploader and caption. If the image predates the claimed event, the claim is false."],
    ["Check for manipulation", "Forensics kit image tools, InVID-WeVerify forensic filters, FotoForensics ELA. Treat ELA as a hint only; recompression creates false positives."],
    ["Assess whether the image is AI-generated", "Look for text gibberish, hands, inconsistent lighting and reflections; detector tools are unreliable — use them as one signal."],
    ["Verify location and time if they matter", "Hand off to the Geolocate a photo or video playbook."],
    ["Record the provenance chain and verdict", "Original / Altered / Miscaptioned / Synthetic / Unverified, with each source archived."]]},

  {id:"pb-video-verify", name:"Video verification", cat:"osint", icon:"play", level:"advanced", time:"1–4 h",
   desc:"Verify where, when and by whom a video was filmed, and whether it shows what it is claimed to show.", steps:[
    ["Download the best available copy with its metadata", "yt-dlp with --write-info-json keeps upload date, uploader and description. Record SHA-256 of the file."],
    ["Find the earliest upload and the original uploader", "Search the platform and others with key phrases; reverse-search keyframes. Re-uploads often trim or add captions."],
    ["Extract keyframes for reverse search", "InVID-WeVerify Keyframes, or ffmpeg -i video.mp4 -vf fps=1 frame_%04d.png. Search the clearest frames on Google Lens, Yandex and TinEye."],
    ["Check container metadata", "exiftool / ffprobe: creation time, encoder, device. Platform-processed files usually lose this."],
    ["Geolocate the scene", "Match skylines, road layouts, signs and terrain against satellite and street-level imagery (Google Earth Pro, Copernicus Browser)."],
    ["Chronolocate from shadows and sun position", "SunCalc.org with the geolocated spot: shadow direction and length give a time window. Account for camera lens distortion."],
    ["Cross-check weather and environment", "Historical weather (e.g. Meteostat, Weather Underground history), season, vegetation, daylight hours."],
    ["Listen to the audio", "Language, dialect, sirens, call to prayer, explosions vs fireworks. Audio can be dubbed — check sync."],
    ["Compare with other footage of the same event", "Different angles should agree on positions, timing and details."],
    ["Look for editing and synthetic signs", "Frame-by-frame review for cuts, warping, lip-sync errors. Deepfake detectors are a weak signal."],
    ["State the verdict with what is confirmed and what is not", "Separate 'location confirmed', 'date confirmed', 'event as claimed'."]]},

  {id:"pb-darkweb-monitor", name:"Dark web & leak site monitoring", cat:"osint", icon:"eye-off", level:"advanced", time:"1–3 h",
   desc:"Check leak sites and forums for your organisation's data, safely and within legal limits.", steps:[
    ["Confirm authorisation and legal guidance on handling stolen data", "Some jurisdictions restrict downloading or possessing leaked personal data. Get counsel's position before any download."],
    ["Use an isolated research environment", "Dedicated VM (e.g. Whonix) or Tails with Tor Browser at the Safest security level; no personal accounts, no shared clipboard, no host-mounted folders."],
    ["Check ransomware leak-site trackers first", "ransomware.live and RansomLook index leak-site posts — often enough to confirm a listing without visiting the site."],
    ["Search for the organisation, domains and brand names", "Ahmia for onion search, tracker sites, and known forums. Note exact victim name used by the group."],
    ["Record each finding with onion URL, timestamp, screenshot and hash", "Capture page text into OSINTrix; screenshots should show the URL and time."],
    ["Assess what is claimed versus what is shown", "File trees and sample documents indicate scope; claims of volume are often inflated. Do not open documents outside the isolated VM."],
    ["Do not engage, pay, or register on criminal forums without authorisation", "Interaction can create legal exposure and tip off the actor."],
    ["Stop immediately and report if you encounter child sexual abuse material", "Do not capture or retain it. Report via your national hotline (e.g. NCMEC, IWF) and to counsel."],
    ["Extract indicators: actor name, contact methods, wallets, onion addresses", "Capture pulls onion links and wallet addresses out of pasted text."],
    ["Brief legal and incident response with findings and confidence", "Data exposure may trigger notification deadlines (e.g. 72 h under GDPR)."],
    ["Set up ongoing monitoring for new posts", "Tracker RSS/alerts or periodic checks; record each check in the case."]]},

  {id:"pb-telegram", name:"Telegram channel investigation", cat:"osint", icon:"message-square", level:"advanced", time:"1–3 h",
   desc:"Map a Telegram channel or group: content, admins, sources and the network it belongs to.", steps:[
    ["View the channel without an account where possible", "Public channels have a web preview at t.me/s/<channelname>. Archive it."],
    ["Use a dedicated research account if you must join", "Separate phone number and device; set phone-number visibility to Nobody. Joining a group can make you visible in the members list."],
    ["Record channel metadata", "Title, username, description, creation date (first message), subscriber count, linked discussion group. Usernames can change — note the numeric ID if available."],
    ["Export the history", "Telegram Desktop → Export chat history (JSON) gives messages, dates and forward sources for offline analysis."],
    ["Map forward sources and mentions", "'Forwarded from' headers reveal source channels; repeated sources indicate a network. Graph them with counts."],
    ["Identify admins, bots and contact handles", "Bios, pinned messages and posts often name @admin contacts and bots used for payments or submissions."],
    ["Extract indicators: links, wallets, phone numbers, emails", "Paste the export into Capture."],
    ["Analyse posting patterns and language", "Posting hours, time zone, language and spelling habits, shared images across channels."],
    ["Use analytics and discovery tools", "TGStat for growth history and mentions; Telegram's similar-channels recommendations; open-source collectors such as Telepathy."],
    ["Assess media for provenance", "Run key images and videos through the Image provenance and Video verification playbooks."],
    ["Summarise the channel's role and network with confidence", "Source, amplifier, marketplace or coordination hub — cite the evidence."]]},

  {id:"pb-breach-exposure", name:"Data-breach exposure check", cat:"osint", icon:"shield-alert", level:"core", time:"30–90 min",
   desc:"Find where your organisation's accounts and credentials appear in breaches and infostealer logs, and act on it.", steps:[
    ["Define the scope: domains, VIP accounts, customer-facing services", "List every corporate and legacy domain."],
    ["Run a domain search on Have I Been Pwned", "Requires domain verification; returns every address in known breaches with breach names and dates."],
    ["Check for infostealer exposure", "Free lookups such as Hudson Rock's infostealer check, or your threat-intel provider. Infostealer logs include session cookies, which bypass MFA."],
    ["Review vendor and threat-intel alerts for leaked credentials", "Identity-protection features (e.g. Entra ID Protection 'Leaked credentials' risk detection)."],
    ["Do not download or buy breach dumps without legal approval", "Possession of stolen personal data can create liability."],
    ["Prioritise accounts: privileged, still active, recent exposure", "Map breached addresses to current accounts in your directory; former staff accounts should be disabled anyway."],
    ["Reset credentials and revoke sessions for exposed active accounts", "Revoke refresh tokens / sessions, not just passwords, for infostealer cases."],
    ["Check exposed passwords against your directory", "HIBP Pwned Passwords k-anonymity API or a banned-password list in your IdP."],
    ["Look for misuse after exposure", "Sign-in logs for the affected accounts from the breach date onward."],
    ["Notify users with clear guidance", "Explain which service was breached and what to change; avoid phishing-like wording."],
    ["Schedule recurring checks and record results", "HIBP domain notifications and a monthly review."]]},

  {id:"pb-transport", name:"Vehicle, aircraft & vessel tracking", cat:"osint", icon:"anchor", level:"advanced", time:"1–3 h",
   desc:"Identify and trace a vehicle, aircraft or ship from registrations and public transponder data.", steps:[
    ["Identify the asset type and the identifiers you have", "Plate, VIN, aircraft registration / ICAO 24-bit hex code, ship name / IMO / MMSI. IMO is permanent; MMSI and names can change."],
    ["Aircraft: look up the registration", "National registries (e.g. FAA N-number registry, UK CAA G-INFO). Owners are often trusts or leasing companies."],
    ["Aircraft: pull flight history from ADS-B", "ADS-B Exchange and ADSB.lol show unfiltered tracks; Flightradar24 filters blocked aircraft; OpenSky has historical data for researchers. Respect privacy programs (LADD/PIA) and your scope."],
    ["Vessels: look up identity and ownership", "Equasis (free registration) gives flag, owner, manager and history; cross-check IMO numbers."],
    ["Vessels: pull AIS position history", "MarineTraffic, VesselFinder, MyShipTracking; Global Fishing Watch highlights AIS gaps and encounters."],
    ["Check for AIS gaps, spoofing and identity swaps", "Sudden jumps, impossible speeds, a ship 'on land', or two vessels with one MMSI. Satellite imagery (Copernicus Browser) can confirm a position."],
    ["Vehicles: identify make, model and plate format", "Plate formats point to country/region. UK DVLA vehicle enquiry gives tax/MOT status (not owner). Owner records are restricted by law (e.g. DPPA in the US) — use only lawful channels."],
    ["Corroborate with imagery and social media", "Spotter photos (e.g. JetPhotos, ShipSpotting), port and airport webcams, geotagged posts."],
    ["Build a movement timeline with sources and gaps", "Send positions to the case timeline and map; mark gaps explicitly."],
    ["Assess significance and confidence", "Owner, operator and user can all differ — say which you have established."]]},

  {id:"pb-site-attribution", name:"Website attribution", cat:"osint", icon:"fingerprint", level:"advanced", time:"1–3 h",
   desc:"Link an anonymous website to its operators and sister sites through shared technical fingerprints.", steps:[
    ["Archive the site and record current DNS, WHOIS/RDAP and hosting", "urlscan.io scan plus Wayback Machine Save Page Now; RDAP for registrar and dates."],
    ["Extract tracking and monetisation IDs from the page source", "Google Analytics (UA-/G-), Tag Manager (GTM-), AdSense (pub-), Meta Pixel, Yandex Metrica. View source and the urlscan DOM."],
    ["Search for other sites sharing those IDs", "DNSlytics, BuiltWith relationships, urlscan.io search, and historic source in the Wayback Machine. Old UA- IDs are especially useful."],
    ["Compute and search the favicon hash", "Shodan http.favicon.hash (MurmurHash3 of the base64 favicon) finds servers serving the same icon — including origin servers behind a CDN."],
    ["Review TLS certificates and subdomains", "crt.sh for all names on shared certs; Censys for hosts presenting the same certificate."],
    ["Pull historical DNS and WHOIS", "SecurityTrails or similar passive DNS; WHOIS history can show pre-privacy registrant details."],
    ["Look for origin IPs behind a CDN", "Historic A records before CDN adoption, mail server (MX) IPs, certificates on non-CDN IPs in Censys."],
    ["Check early archived versions for real names and contact details", "Early Wayback snapshots, robots.txt, sitemap.xml, about/contact pages, author meta tags, comments in HTML."],
    ["Collect payment and contact indicators", "Crypto wallets, PayPal/Stripe handles, phone numbers, emails — Capture extracts them."],
    ["Graph the cluster with evidence on each link and rate confidence", "Shared analytics ID is strong; shared hosting IP on a CDN is weak."]]},

  {id:"pb-disinfo", name:"Disinformation narrative tracking", cat:"osint", icon:"newspaper", level:"advanced", time:"2–6 h",
   desc:"Trace a false or misleading narrative to its origin, map how it spread and assess who is behind it.", steps:[
    ["State the narrative and the specific claims precisely", "One sentence per claim. Vague narratives cannot be tracked or fact-checked."],
    ["Check existing fact-checks", "Google Fact Check Explorer and IFCN signatory fact-checkers."],
    ["Collect and archive examples across platforms", "Archive rather than link to avoid amplifying. Record post URL, account, time, engagement."],
    ["Find the earliest appearance", "Search distinctive phrases, hashtags and media; sort by date. Reverse-search images and keyframes for first use."],
    ["Identify seeding and amplifying accounts", "Use the Social account authenticity playbook on the top spreaders."],
    ["Map cross-platform spread over time", "Timeline of first appearance per platform and language; note jumps from fringe to mainstream."],
    ["Describe behaviour with a shared framework", "ABCDE (Actor, Behaviour, Content, Degree, Effect) or DISARM techniques make reports comparable."],
    ["Assess reach without overstating it", "Engagement can be inflated by bots; distinguish views, shares and genuine interactions."],
    ["Assess attribution with explicit confidence", "Distinguish who created, who amplified and who benefited. Estimative language (likely, almost certainly)."],
    ["Write findings without repeating the false claim as headline", "Lead with the fact, then the falsehood, then the correction (truth sandwich)."],
    ["Share with platforms or partners as appropriate and record outcome", "Keep archives in case content is removed."]]},
  /* ------------------------------------------------------------------- IR */
  {id:"pb-bec", name:"Business email compromise", cat:"ir", icon:"briefcase", level:"core", time:"2–6 h",
   desc:"Respond to a fraudulent payment request or hijacked mail thread: stop the money, find the entry point, scope the exposure.", steps:[
    ["Contact finance and the bank immediately if money has moved", "Ask the sending bank for a recall / fraud hold — the first 24–72 h matter most. In the US report to FBI IC3 promptly; in the UK report to Action Fraud / Report Fraud."],
    ["Decide which scenario this is: our mailbox, the supplier's mailbox, or a look-alike domain", "Check the sending domain character by character and the headers. Look-alike = external; genuine domain with valid DKIM = a real mailbox was used."],
    ["Preserve the fraudulent messages with full headers", "Export .eml/.msg; screenshots are not enough."],
    ["If our mailbox: review sign-in logs for the user", "Entra sign-in logs (interactive and non-interactive): new IPs, countries, user agents, and a session reused from a different IP shortly after a legitimate login (AiTM token theft)."],
    ["Check for inbox rules and forwarding", "Get-InboxRule and Get-Mailbox (ForwardingSmtpAddress / ForwardingAddress). BEC rules commonly move mail with 'invoice', 'payment' or the supplier's name to RSS Feeds or Archive."],
    ["Check MFA methods and app consents added recently", "Entra audit log: 'User registered security info', 'Consent to application'."],
    ["Find what the attacker read and sent", "Unified Audit Log MailItemsAccessed and Send operations; message trace for outbound mail during the compromise window."],
    ["Contain: reset password, revoke sessions, remove rules, remove rogue MFA methods", "Revoke-MgUserSignInSession; disable the account first if still active."],
    ["Identify every external party who received attacker mail", "They may have been sent the same fraudulent bank details — warn them by phone, not email."],
    ["Block the look-alike domains and attacker infrastructure", "Transport rule / tenant block list; report look-alike domains to the registrar."],
    ["Run the full mailbox playbook if the account was compromised", "See M365 mailbox compromise for deeper scoping."],
    ["Fix the payment process", "Out-of-band call-back to a known number for any bank-detail change; dual approval for new payees."]]},

  {id:"pb-insider-exfil", name:"Insider threat / data exfiltration", cat:"ir", icon:"file-output", level:"advanced", time:"1–3 days",
   desc:"Investigate suspected data theft by an employee or contractor, discreetly and with HR and legal in the loop.", steps:[
    ["Engage HR and legal before collecting, and agree the authority to investigate", "Employee monitoring is regulated; confirm policy, consent clauses and works-council rules. Keep the circle need-to-know."],
    ["Define the data at risk and the time window", "Which repositories, what classification, notice/resignation date. Most exfiltration happens in the 30 days before leaving."],
    ["Preserve evidence without tipping off the subject", "Legal hold on mailbox and cloud drive, quiet triage collection of the endpoint (KAPE / Velociraptor)."],
    ["Review DLP and CASB alerts for the user", "Uploads to personal cloud storage, email to personal addresses, large attachments, encrypted archives."],
    ["Check removable media use", "USBSTOR and MountedDevices registry keys, setupapi.dev.log, Microsoft-Windows-Partition/Diagnostic event 1006, Event 6416 (new external device) if auditing is enabled."],
    ["Check cloud and SaaS downloads", "M365 Unified Audit Log: FileDownloaded, FileSyncDownloadedFull, FileAccessed; Google Workspace Drive audit; source-code platform clone and download logs."],
    ["Check email to personal or competitor addresses", "Message trace for external recipients, attachment sizes and file names."],
    ["Review file access artefacts on the endpoint", "LNK files and jump lists (LECmd, JLECmd), ShellBags (SBECmd), recent-files MRUs — shows files opened from USB or shares."],
    ["Compare against the user's baseline and role", "Volume spikes and access outside normal duties matter more than raw counts."],
    ["Check printing and screenshots if relevant", "Print server logs, Microsoft-Windows-PrintService/Operational event 307."],
    ["Build a factual timeline without conclusions about intent", "Leave intent to HR/legal. Every entry cites its source artefact."],
    ["Recommend actions: access removal, device return, legal letters", "Revoke access at the agreed time — ideally coordinated with the HR conversation."]]},

  {id:"pb-webshell", name:"Web server compromise / webshell", cat:"ir", icon:"file-code", level:"core", time:"2–6 h",
   desc:"Confirm a webshell, find how it got there and what the attacker did through it.", steps:[
    ["Preserve the server state before cleaning", "Memory and disk snapshot (VM snapshot or image), copies of web root and logs. Do not delete the shell yet."],
    ["Find candidate webshells in the web roots", "Recently modified scripts (.php, .jsp, .aspx, .ashx): find <webroot> -newermt <date> -type f. Scan with YARA (e.g. Neo23x0 signature-base) or THOR Lite / LOKI."],
    ["Inspect suspicious files safely", "Look for eval, base64_decode, assert, system, Runtime.exec, Process.Start with request parameters. Decode obfuscation in Decoder."],
    ["Search access logs for requests to the shell", "IIS (W3SVC*\\u_ex*.log), Apache/Nginx access.log: POSTs to unusual files, single IPs, odd user agents. The first request shows when it was used."],
    ["Find the initial exploitation", "Requests just before the shell's creation time: upload endpoints, known CVE paths, path traversal. Match against the vendor advisory."],
    ["Check process creation from the web server process", "w3wp.exe, httpd, php-fpm, java or tomcat spawning cmd.exe, powershell.exe, sh or bash (Sysmon 1 / 4688 / EDR)."],
    ["Identify commands run and data accessed", "Shell parameters in logs (GET), EDR command lines, database query logs."],
    ["Check for persistence and further footholds", "Additional shells, new local or app accounts, scheduled tasks / cron, modified config files, SSH keys."],
    ["Check for lateral movement from the server", "Outbound connections to internal hosts, credential use from the server's account."],
    ["Extract and block indicators", "Attacker IPs, shell file hashes and names; Detections → Generate from case for a starting rule."],
    ["Remediate: patch, rebuild or restore from known-good, rotate secrets", "Rotate DB credentials, API keys and machine keys stored on the server."],
    ["Add monitoring for the web root and web-process child processes", "File integrity monitoring and a detection on web-server spawning a shell."]]},

  {id:"pb-lateral-movement", name:"Lateral movement hunt", cat:"ir", icon:"route", level:"advanced", time:"4–8 h",
   desc:"Trace how an attacker moved between Windows hosts from logon events, services and remote-execution artefacts.", steps:[
    ["Collect Security, System and relevant Operational EVTX from in-scope hosts and DCs", "KAPE target EventLogs or Velociraptor Windows.KapeFiles.Targets; include TerminalServices, WinRM, WMI-Activity, PowerShell and Sysmon logs."],
    ["Run Hayabusa or Chainsaw over the logs for a first pass", "Hayabusa csv-timeline / Chainsaw hunt with Sigma rules — gives a prioritised starting list."],
    ["Map network logons by source and destination", "4624 logon type 3 (network) and 10 (RemoteInteractive) with source IP and account; 4648 explicit credentials on the source host."],
    ["Check RDP artefacts", "TerminalServices-RemoteConnectionManager 1149, LocalSessionManager 21/24/25; on the source: Default.rdp, Terminal Server Client registry MRU, bitmap cache."],
    ["Check PsExec and service-based execution", "System 7045 / Security 4697 new service (e.g. PSEXESVC or random names), 5145 access to ADMIN$/IPC$."],
    ["Check WMI and WinRM execution", "WmiPrvSE.exe or wsmprovhost.exe spawning processes (4688 / Sysmon 1); WinRM Operational 91; WMI-Activity 5857–5861 for persistence."],
    ["Check scheduled tasks created remotely", "4698 and Microsoft-Windows-TaskScheduler/Operational 106; tasks folder on the target."],
    ["Look for pass-the-hash and pass-the-ticket signs", "4624 logon type 9 with seclogo, NTLM network logons where Kerberos is expected, 4769 with RC4 (0x17) tickets."],
    ["Build the host-to-host movement graph and timeline", "Each edge = account + method + time + evidence; it shows patient zero and the furthest point reached."],
    ["Check identity paths the attacker could use next", "BloodHound / PingCastle on AD to find the privilege paths from compromised accounts."],
    ["Hunt the same patterns estate-wide", "Velociraptor hunts or SIEM queries for the accounts, tools and service names found."],
    ["Contain: reset used accounts, block movement paths", "Disable compromised accounts, restrict admin shares and remote management to admin jump hosts."]]},

  {id:"pb-ad-compromise", name:"Active Directory compromise", cat:"ir", icon:"shield", level:"advanced", time:"1–3 days",
   desc:"Assess whether the domain itself is compromised — DCSync, forged tickets, rogue admins — and plan recovery.", steps:[
    ["Collect DC Security logs and enable missing audit policy", "Directory Service Access, Kerberos Service Ticket Operations, Account Management, Security Group Management. Logs roll fast on DCs — export now."],
    ["Check for DCSync", "4662 on DCs with DS-Replication-Get-Changes / Get-Changes-All rights (GUIDs 1131f6aa-… and 1131f6ad-…) by accounts that are not DCs; DRSUAPI replication traffic from non-DC IPs."],
    ["Check for NTDS.dit theft", "ntdsutil 'ifm', vssadmin create shadow, copies of ntds.dit or SYSTEM hive; 4688 / Sysmon 1 on DCs."],
    ["Look for golden ticket indicators", "4769 service tickets without a matching 4768 TGT request, accounts or SIDs that do not exist, RC4 tickets where AES is enforced, ticket lifetimes beyond policy."],
    ["Look for Kerberoasting and AS-REP roasting", "Bursts of 4769 with encryption type 0x17 for many SPNs from one account; 4768 with pre-auth type 0 for accounts with 'Do not require Kerberos preauthentication'."],
    ["Review privileged group changes", "4728 / 4732 / 4756 adds to Domain Admins, Enterprise Admins, Administrators, Schema Admins, Backup Operators; 4720 new accounts."],
    ["Check AD persistence mechanisms", "AdminSDHolder ACL changes, SIDHistory on accounts, new GPOs or GPO scripts, delegation changes (msDS-AllowedToActOnBehalfOfOtherIdentity), rogue DC objects, certificate templates (AD CS)."],
    ["Assess AD security posture", "PingCastle, Purple Knight or BloodHound to find attack paths and dangerous ACLs that may have been used."],
    ["Decide on scope: targeted accounts or the whole forest", "Evidence of DCSync, NTDS theft or a golden ticket means assume every credential in the domain is exposed."],
    ["Plan krbtgt reset (twice) and privileged credential rotation", "Reset krbtgt, wait for replication and ticket lifetime (10 h default), then reset again. Use Microsoft's reset script and test replication first."],
    ["Rotate service accounts, AD CS, trusts and Entra Connect credentials", "Remove unknown certificate enrolments and revoke suspicious certificates."],
    ["Record a recovery plan and validate with a post-recovery assessment", "Re-run PingCastle / BloodHound; confirm no unknown admins remain."]]},

  {id:"pb-endpoint-triage", name:"Endpoint triage with KAPE / Velociraptor", cat:"ir", icon:"monitor", level:"core", time:"1–3 h",
   desc:"Collect and review a fast triage package from a suspect Windows endpoint without imaging the whole disk.", steps:[
    ["Decide whether to capture memory first", "If malware may be running or disk is encrypted, capture RAM (WinPmem, Magnet RAM Capture, DumpIt) before triage collection. Record BitLocker recovery key if applicable."],
    ["Collect the triage package", "KAPE target !SANS_Triage or KapeTriage to an external drive / share; or Velociraptor Windows.KapeFiles.Targets. Record collection time and SHA-256 of the output."],
    ["Parse artefacts", "KAPE module !EZParser (Eric Zimmerman tools) produces CSVs; open them in Timeline Explorer."],
    ["List running processes and network connections", "Velociraptor Windows.System.Pslist and Windows.Network.Netstat; look for unsigned binaries in user-writable paths and unknown outbound connections."],
    ["Review persistence", "Windows.Sysinternals.Autoruns or Autoruns: Run keys, services, scheduled tasks, WMI subscriptions, startup folders."],
    ["Review execution evidence", "Prefetch (PECmd), Amcache (AmcacheParser), ShimCache (AppCompatCacheParser), BAM; focus on the incident window."],
    ["Review event logs for logons, services and PowerShell", "Hayabusa / Chainsaw on the EVTX; 4624, 4688, 7045, 4104 script blocks."],
    ["Check user activity around the time of interest", "Browser history (SQLite viewer), downloads folder, LNK / jump lists, recycle bin (RBCmd)."],
    ["Hash and reputation-check suspicious files", "Collect the binaries; VirusTotal by hash first, upload only if allowed."],
    ["Decide: clean, contain or escalate to full forensics", "Write the rationale. Escalate when you find credential theft, persistence or lateral movement."],
    ["Send key findings to the case timeline", "Each row with its source artefact and time zone (UTC)."]]},

  {id:"pb-edge-device", name:"VPN / edge device compromise", cat:"ir", icon:"lock-open", level:"advanced", time:"4 h–2 days",
   desc:"Respond to suspected exploitation of a firewall, VPN or gateway appliance where EDR cannot run.", steps:[
    ["Identify the device, firmware version and the vulnerability", "Vendor advisory and CISA KEV; note whether exploitation is known in the wild."],
    ["Collect logs and diagnostics before patching or rebooting", "Some upgrades and reboots wipe evidence. Export system, VPN, admin and configuration logs, plus the vendor's support/diagnostic bundle."],
    ["Run the vendor integrity or IoC checker where one exists", "e.g. Ivanti Integrity Checker Tool (external version), vendor-published scripts. A clean result is not proof — attackers have tampered with checkers."],
    ["Pull external logs that the device cannot tamper with", "Syslog/SIEM copies, NetFlow, upstream firewall logs."],
    ["Look for exploitation requests and odd admin activity", "Unusual URLs in web logs, admin logins from unknown IPs, configuration changes, new local accounts, new files in web directories."],
    ["Check outbound connections from the appliance itself", "Appliances rarely initiate outbound connections other than updates, DNS and auth — anything else is suspicious."],
    ["Assume credentials that passed through the device are exposed", "VPN user credentials, the LDAP/RADIUS bind account, local admin, certificates and keys on the device."],
    ["Hunt for follow-on activity inside the network", "Logons from the VPN pool or appliance IP to internal hosts; use the Lateral movement playbook."],
    ["Contain: restrict management interfaces and block known attacker IPs", "Management interfaces should never be internet-facing."],
    ["Remediate per vendor guidance: factory reset / rebuild, patch, restore clean config", "Do not restore a configuration backup taken after compromise without review."],
    ["Rotate all affected credentials and certificates", "Include the device's own TLS and VPN certificates."],
    ["Add monitoring for the device class", "Forward logs off-box, alert on admin logins and config changes."]]},

  {id:"pb-supply-chain", name:"Supply-chain / malicious package", cat:"ir", icon:"box", level:"advanced", time:"2–8 h",
   desc:"Find whether a malicious or compromised dependency reached your code, build systems or users — and clean up.", steps:[
    ["Confirm the advisory: package, ecosystem, affected versions and behaviour", "OSV.dev, GitHub Advisory Database, the registry's notice and the researcher's write-up."],
    ["Search all repositories for the package and versions", "Lockfiles (package-lock.json, yarn.lock, pnpm-lock.yaml, poetry.lock, requirements.txt, go.sum). OSV-Scanner or Grype across repos; npm ls <pkg> for transitive use."],
    ["Check build and CI logs for installs of the bad version in the window", "CI job logs, artifact caches, container image layers (syft to generate SBOMs)."],
    ["Determine what the payload does", "Install scripts (preinstall/postinstall in package.json, setup.py), obfuscated code; vendor analyses such as Socket or OpenSSF Package Analysis."],
    ["Identify systems where it executed", "Developer workstations, CI runners, production containers. Install-time payloads run where npm install / pip install ran."],
    ["Treat secrets on those systems as compromised", "CI secrets, cloud keys, npm/PyPI tokens, SSH keys, GitHub tokens, .env files. Check environment variables available to the job."],
    ["Hunt for the payload's indicators", "Network destinations, dropped files, persistence; EDR and DNS logs."],
    ["Remove the package, pin a safe version and rebuild", "Clear caches and rebuild images from clean bases; redeploy."],
    ["Rotate exposed secrets and review their use", "Check CloudTrail / GitHub audit log for use of the tokens after the exposure time."],
    ["Check whether you published anything affected", "If your own packages or releases were built with it, notify downstream users."],
    ["Report and add controls", "Report to the registry if new; enforce lockfiles, package age or allow-lists, and secret scoping in CI."]]},

  {id:"pb-containment", name:"Containment & eradication checklist", cat:"ir", icon:"shield-check", level:"core", time:"2–8 h",
   desc:"Coordinate containment and eradication so the attacker is removed in one move, not chased around the network.", steps:[
    ["Confirm scope is good enough to act", "Known compromised hosts, accounts, persistence and C2. Acting too early tips the attacker off; too late lets damage continue."],
    ["Agree the containment plan, time and owners", "One coordinated window; list every action, who does it and how it is verified."],
    ["Preserve evidence for anything you will change", "Memory and triage collection, log exports, VM snapshots."],
    ["Isolate compromised hosts", "EDR network isolation keeps the agent connected; avoid powering off."],
    ["Block attacker infrastructure", "Firewall, proxy, DNS sinkhole for C2 domains/IPs; email blocks for phishing senders."],
    ["Disable or reset compromised accounts and revoke sessions and tokens", "Include service accounts, cloud keys, OAuth grants, VPN certs. For domain compromise follow the AD playbook (krbtgt twice)."],
    ["Remove persistence", "Services, scheduled tasks, Run keys, WMI subscriptions, webshells, new accounts, rogue OAuth apps, cloud IAM changes."],
    ["Rebuild or reimage where trust cannot be restored", "Servers with rootkits, DCs with suspected tampering, edge devices — rebuild from known-good."],
    ["Patch or mitigate the entry point", "Close the initial access vector before reconnecting systems."],
    ["Monitor closely for re-entry", "Heightened alerting on the known indicators and techniques for at least 30 days."],
    ["Verify eradication", "Re-hunt the indicators and techniques; confirm no beaconing or new persistence."],
    ["Record every action with timestamp and operator", "Needed for the report, insurers and regulators."]]},

  {id:"pb-post-incident", name:"Post-incident report & lessons learned", cat:"ir", icon:"file-text", level:"core", time:"1–2 days",
   desc:"Turn the case into a clear report and a short list of improvements that actually get done.", steps:[
    ["Freeze the timeline and evidence list", "Every key event in UTC with its source; reconcile conflicting times."],
    ["Write the executive summary in plain language", "What happened, impact, current status, top three actions. One page."],
    ["Describe the attack chain", "Initial access → execution → persistence → movement → objectives, mapped to ATT&CK techniques."],
    ["State impact precisely", "Systems, accounts, data types and records affected; what is confirmed versus assumed."],
    ["Record the response actions and their timing", "Detection time, containment time, eradication, recovery — these become your metrics (time to detect / contain)."],
    ["Confirm regulatory, contractual and notification obligations are met", "Data-protection regulator, customers, insurers, law enforcement; record dates sent."],
    ["Run a blameless lessons-learned session", "What went well, what slowed us down, what we got lucky on. Focus on systems and process."],
    ["Agree improvement actions with owners and dates", "Each one specific and testable (e.g. 'enforce phishing-resistant MFA for admins by 1 March')."],
    ["Update detections, playbooks and runbooks", "Add the case's indicators and behaviours to Detections; adjust this playbook set."],
    ["Share indicators with trusted partners at the right TLP", "ISAC/ISAO, MISP communities — strip victim data."],
    ["Sign off the report and store it with the case evidence", "Version, approver and distribution list."]]},
  /* --------------------------------------------------------------- THREAT */
  {id:"pb-actor-profile", name:"Threat actor profiling", cat:"threat", icon:"target", level:"advanced", time:"1–3 days",
   desc:"Build a structured, sourced profile of a threat actor relevant to your organisation using the diamond model.", steps:[
    ["Write the intelligence requirement the profile must answer", "e.g. 'How likely is actor X to target our sector in the next 6 months, and how?' — keeps the work focused."],
    ["Reconcile the actor's names across vendors", "MITRE ATT&CK Groups, Malpedia and vendor naming crosswalks; names overlap imperfectly — record which reports each alias comes from."],
    ["Collect and grade sources", "Vendor reports, government advisories (CISA, NCSC), your own incidents. Grade reliability and credibility (Admiralty code)."],
    ["Diamond model — adversary", "Suspected sponsor or motivation (espionage, financial, hacktivist), operating hours, language artefacts. Keep attribution claims sourced."],
    ["Diamond model — capability", "Malware families, tools, exploits used; map to ATT&CK techniques and build an ATT&CK Navigator layer."],
    ["Diamond model — infrastructure", "Domains, IPs, hosting preferences, certificate and registration patterns; use the C2 pivoting playbook to extend."],
    ["Diamond model — victims", "Sectors, regions, organisation size, and how they were selected."],
    ["Identify the actor's typical initial access and objectives", "Phishing, edge-device exploits, valid accounts; data theft, extortion, disruption."],
    ["Compare against your own exposure and controls", "Which techniques would work against you today? Gaps become detection and hardening priorities."],
    ["Turn the capability layer into detections and hunts", "Detections → map techniques to rules; schedule hunts for the top techniques."],
    ["Write the profile with confidence statements and review date", "Estimative language, key assumptions, intelligence gaps. Set TLP before sharing."]]},

  {id:"pb-phishkit-hunt", name:"Phishing kit & infrastructure hunting", cat:"threat", icon:"scan-search", level:"advanced", time:"2–4 h",
   desc:"Find phishing pages impersonating your brand, the kit behind them and the infrastructure that hosts them.", steps:[
    ["Generate look-alike domains for your brand", "dnstwist for typos, homoglyphs and TLD swaps; check which are registered and resolve."],
    ["Watch certificate transparency for brand keywords", "crt.sh searches (e.g. %yourbrand%) and certstream-based monitors catch new phishing sites when they get TLS."],
    ["Search urlscan.io for pages that look like yours", "Search by page title, your logo/favicon hash, domain keywords, or the hash of a known kit resource."],
    ["Analyse a live phishing page safely", "urlscan.io or a sandbox browser; note form POST targets, JavaScript exfil endpoints, Telegram bot API calls, anti-bot checks."],
    ["Look for exposed kit archives and open directories", "Kits are often left as .zip files in the web root. Download only into an isolated environment; never run them."],
    ["Extract kit fingerprints", "Unique file names, comments, author handles, exfil emails or Telegram bot IDs, .htaccess block lists — these link campaigns."],
    ["Pivot on kit fingerprints to find sibling sites", "urlscan.io hash and filename search, Shodan/Censys http.html_hash and favicon hash, shared hosting and registrar patterns."],
    ["Check reputation feeds for known reports", "PhishTank, OpenPhish, URLhaus, VirusTotal."],
    ["Record indicators and decide on action", "Blocklist internally, report for takedown (see Scam website takedown playbook), notify users if credentials were harvested."],
    ["Set up continuing monitoring", "Saved urlscan searches, CT alerts and periodic dnstwist runs."]]},

  {id:"pb-c2-pivot", name:"C2 infrastructure pivoting", cat:"threat", icon:"radar", level:"advanced", time:"2–6 h",
   desc:"Expand from one C2 indicator to the wider server cluster using certificates, TLS fingerprints and banners.", steps:[
    ["Start from a confirmed indicator with context", "IP, domain or URL from a sample, sandbox or incident. Record the source and first-seen time."],
    ["Profile the server passively", "Shodan and Censys: open ports, banners, HTTP headers, certificates, history. Avoid active scanning of attacker infrastructure unless policy allows."],
    ["Pivot on the TLS certificate", "Censys/Shodan search by certificate SHA-256, serial, subject or issuer. Default or self-signed certs from C2 frameworks are strong pivots (e.g. Cobalt Strike's well-known default cert)."],
    ["Pivot on TLS and HTTP fingerprints", "JARM (Shodan ssl.jarm), JA4+ fingerprints (JA4S, JA4X, JA4H) where your data source supports them. JARM alone is noisy — combine with another feature."],
    ["Pivot on HTTP response features", "Shodan http.html_hash, http.favicon.hash, unique header order or default 404 pages of frameworks."],
    ["Pivot on DNS and registration", "Passive DNS (SecurityTrails), shared name servers, registrar and registration time clusters, crt.sh for sibling names."],
    ["Extract config from samples if available", "Beacon config parsers (e.g. SentinelOne CobaltStrikeParser, Didier Stevens' 1768.py) give C2 hosts, watermarks and malleable profile details."],
    ["Check threat-intel sources for the cluster", "ThreatFox, Feodo Tracker, URLhaus, VirusTotal relations, vendor reports."],
    ["Score each new indicator's confidence", "High: same cert + same JARM + same unusual port. Low: same ASN only."],
    ["Check internal telemetry for any of the new indicators", "DNS, proxy and firewall logs over the retention period."],
    ["Publish the cluster as blocklist and detections with expiry", "C2 infrastructure rotates; set review dates on blocks."]]},

  {id:"pb-vuln-itw", name:"Vulnerability exploited in the wild — triage", cat:"threat", icon:"triangle-alert", level:"core", time:"1–4 h",
   desc:"Decide quickly how exposed you are to a newly exploited vulnerability and whether you are already compromised.", steps:[
    ["Read the primary advisory and confirm exploitation status", "Vendor advisory, CISA KEV entry, NVD record; note affected versions, fixed versions and prerequisites."],
    ["Check exploitation likelihood and activity", "EPSS score (FIRST), GreyNoise tags for mass exploitation, vendor and researcher reports."],
    ["Find every affected asset you own", "CMDB and vulnerability scanner, plus external view: Shodan / Censys queries for your IP ranges and domains. Shadow IT shows up here."],
    ["Rank assets by exposure", "Internet-facing and unauthenticated first; then internal; then those behind compensating controls."],
    ["Check for signs of exploitation before patching", "Vendor-published IoCs, web/app logs for the exploit path, new files, unexpected child processes. Patching does not remove an existing compromise."],
    ["Apply the patch or the vendor's mitigation", "If you cannot patch, apply the mitigation or remove internet exposure, and record the risk acceptance."],
    ["Verify the fix", "Version check or an authenticated scanner check; nuclei templates on your own assets only."],
    ["Deploy detections for exploitation attempts", "WAF/IDS signatures, Sigma rules from Detections, log alerts on the exploit path."],
    ["Communicate status to stakeholders", "Exposed / patched / mitigated / compromised counts, with owners for the remainder."],
    ["Open an incident if compromise indicators are found", "Hand off to the relevant IR playbook (Web server compromise, Edge device)."]]},

  /* ---------------------------------------------------------------- CLOUD */
  {id:"pb-aws-compromise", name:"AWS account compromise", cat:"cloud", icon:"cloud", level:"advanced", time:"4 h–2 days",
   desc:"Scope and contain attacker activity across an AWS account or organisation using CloudTrail and IAM evidence.", steps:[
    ["Confirm CloudTrail coverage and preserve logs", "Organisation trail in all regions, log bucket with versioning / object lock. Copy relevant logs to a separate forensic account."],
    ["Identify the compromised principals", "CloudTrail userIdentity (arn, accessKeyId, sessionContext) for suspicious events; GuardDuty findings."],
    ["Check for defence evasion", "StopLogging, DeleteTrail, UpdateTrail, PutEventSelectors, DeleteDetector / UpdateDetector (GuardDuty), DeleteFlowLogs, config recorder changes."],
    ["Check for persistence", "CreateUser, CreateAccessKey, CreateLoginProfile, UpdateLoginProfile, AttachUserPolicy, PutUserPolicy, CreateRole, UpdateAssumeRolePolicy, new SAML/OIDC providers, new Lambda functions."],
    ["Check for privilege escalation", "iam:PassRole with RunInstances or CreateFunction, AttachRolePolicy, CreatePolicyVersion with SetAsDefault, AssumeRole chains to admin roles."],
    ["Check for resource abuse", "RunInstances in unused regions (often large GPU instances for mining), CreateKeyPair / ImportKeyPair, service quota requests, unexpected billing spikes."],
    ["Check for data access and exfiltration", "S3 data events (GetObject volume), PutBucketPolicy / PutBucketAcl / DeletePublicAccessBlock, ModifySnapshotAttribute, ModifyImageAttribute, ModifyDBSnapshotAttribute (sharing to other accounts), GetSecretValue, GetParameter."],
    ["Check for organisation-level actions", "LeaveOrganization, CreateAccount, InviteAccountToOrganization, changes to SCPs."],
    ["Query efficiently", "CloudTrail Lake or Athena over the trail bucket; or open the export in Cloud → Log hunting. Filter by accessKeyId and sourceIPAddress."],
    ["Contain without destroying evidence", "Deactivate keys (update-access-key --status Inactive), attach a deny-all policy, revoke role sessions (IAM 'Revoke active sessions'), isolate instances with a restrictive security group, snapshot EBS volumes."],
    ["Eradicate persistence and rotate credentials", "Remove attacker-created users, keys, roles, functions and trust policy changes; rotate secrets the principals could read."],
    ["Close the gap and record the timeline", "How the credential leaked; enforce SCP guardrails, IMDSv2, least privilege. Send flagged events to the case timeline."]]},

  {id:"pb-leaked-key", name:"Leaked access key response", cat:"cloud", icon:"key-round", level:"core", time:"30–90 min",
   desc:"A cloud key or token was exposed (public repo, paste, ticket, log) — contain it fast and check what it did.", steps:[
    ["Record where, when and how the secret was exposed", "Repo URL and commit, paste link, ticket number; first exposure time sets the investigation window. Public GitHub commits are scraped within minutes."],
    ["Identify the secret type and owner", "AWS AKIA… (long-term) vs ASIA… (temporary), Azure client secret, GCP service-account JSON, GitHub / npm / Slack tokens. AWS: aws sts get-caller-identity tells you the principal."],
    ["Check whether the provider already acted", "AWS may attach the AWSCompromisedKeyQuarantine managed policy and open a support case; GitHub secret scanning partners may revoke tokens automatically."],
    ["Deactivate or revoke the secret now", "Deactivate before deleting so you keep the key ID for log searches. Create a replacement for the legitimate workload."],
    ["Pull all activity for the key since exposure", "CloudTrail filtered by accessKeyId; Entra service principal sign-ins; GCP audit logs by principal; GitHub audit log for tokens."],
    ["Look for actions the owner did not perform", "Unknown source IPs or user agents, enumeration calls (GetCallerIdentity, ListBuckets, ListUsers), persistence (CreateAccessKey, CreateUser)."],
    ["Scope what the key could reach", "Attached and inline policies, assumable roles; treat every secret it could read as exposed too."],
    ["Escalate to full compromise response if misuse is found", "Hand off to AWS account compromise or Azure / Entra tenant compromise."],
    ["Remove the secret from the source and its history", "Rewriting history does not undo exposure — rotation is the fix. Delete pastes and request cache removal."],
    ["Add prevention", "Pre-commit and server-side secret scanning (gitleaks, trufflehog, GitHub push protection); prefer short-lived credentials and workload identity."]]},

  {id:"pb-entra-tenant", name:"Azure / Entra tenant compromise & OAuth consent phishing", cat:"cloud", icon:"users", level:"advanced", time:"4 h–2 days",
   desc:"Investigate attacker access to a Microsoft Entra ID tenant, including malicious app consents and rogue service principals.", steps:[
    ["Export Entra sign-in and audit logs before they age out", "Free tiers keep 7 days, premium 30. Microsoft-Extractor-Suite or CISA's Untitled Goose Tool collect sign-ins, audit and UAL."],
    ["Identify compromised users and risky sign-ins", "Sign-in logs (interactive, non-interactive, service principal); ID Protection risk detections; unusual countries, ASNs, user agents."],
    ["Check for malicious OAuth consent", "Audit log 'Consent to application', 'Add delegated permission grant', 'Add app role assignment to service principal'. Look for Mail.Read, Mail.Send, Files.ReadWrite.All, offline_access on unverified publishers."],
    ["Review service principals and app registrations for new credentials", "'Add service principal', 'Update application – Certificates and secrets management', 'Add owner to application' — a common persistence path."],
    ["Review role assignments and PIM activations", "'Add member to role' for Global Administrator, Privileged Role Administrator, Application Administrator."],
    ["Check for federation and authentication backdoors", "'Set federation settings on domain', 'Set domain authentication', new or modified custom domains, changes to cross-tenant access or conditional access policies."],
    ["Check MFA and authentication method changes", "'User registered security info', new FIDO2 / authenticator devices, Temporary Access Pass issuance."],
    ["Check Azure resource activity if subscriptions exist", "Azure Activity Log: role assignments (Microsoft.Authorization/roleAssignments/write), VM run commands, key vault secret reads, new resources."],
    ["Contain: disable users, revoke sessions, remove consents and app credentials", "Revoke-MgUserSignInSession; delete the oauth2PermissionGrant or disable the service principal; remove rogue secrets/certs."],
    ["Harden: restrict user consent, require admin consent workflow", "Allow user consent only for verified publishers and low-risk permissions; conditional access for admins with phishing-resistant MFA."],
    ["Review mailbox and SharePoint impact for affected accounts", "Hand off to M365 mailbox compromise for each user."],
    ["Record the timeline and the entry point", "AiTM phishing, device-code phishing, password spray, consent phishing — the fix differs for each."]]},

  {id:"pb-m365-mailbox", name:"M365 mailbox compromise", cat:"cloud", icon:"mail", level:"core", time:"2–4 h",
   desc:"Find out what an attacker did inside a Microsoft 365 mailbox, and close every way back in.", steps:[
    ["Confirm audit logging and export the Unified Audit Log for the user", "Search-UnifiedAuditLog or Purview Audit; Microsoft-Extractor-Suite for bulk. Use a window from 30 days before first suspicion."],
    ["Review sign-ins for attacker sessions", "Entra sign-in logs: new IP/ASN, impossible travel, same session ID from two IPs (AiTM token replay), legacy protocols."],
    ["List inbox rules and when they were created", "Get-InboxRule -Mailbox; UAL New-InboxRule / Set-InboxRule / UpdateInboxRules. Short names like '.' or '..' and moves to RSS Feeds are classic."],
    ["Check forwarding and delegation", "Get-Mailbox: ForwardingSmtpAddress, DeliverToMailboxAndForward; UAL Set-Mailbox, Add-MailboxPermission, Add-MailboxFolderPermission, Add-RecipientPermission (SendAs)."],
    ["Determine what mail was accessed", "UAL MailItemsAccessed (Bind / Sync) with session IDs from attacker sign-ins; Sync events mean the whole folder was downloaded."],
    ["Determine what mail was sent and deleted", "UAL Send, SoftDelete, HardDelete, MoveToDeletedItems; message trace for outbound to external recipients."],
    ["Check OneDrive / SharePoint access", "UAL FileAccessed, FileDownloaded, AnonymousLinkCreated, SharingSet."],
    ["Check MFA methods and OAuth apps for the user", "New authentication methods and consented apps — remove anything unrecognised."],
    ["Contain", "Reset password, Revoke-MgUserSignInSession, remove rules/forwarding/delegations, remove rogue methods and app grants; block sign-in if needed."],
    ["Purge malicious mail sent internally and warn external recipients", "Compliance search & purge; call key partners."],
    ["Assess data exposure for notification", "Classify accessed mail and files; involve privacy/legal if personal data was accessed."],
    ["Add protections", "Phishing-resistant MFA, block external auto-forwarding, alert on new inbox rules with forwarding or deletion."]]},

  {id:"pb-k8s", name:"Kubernetes cluster compromise", cat:"cloud", icon:"layers", level:"advanced", time:"4 h–2 days",
   desc:"Investigate suspicious workloads or API access in a Kubernetes cluster and remove the attacker's footholds.", steps:[
    ["Confirm audit logging and preserve it", "Managed clusters: EKS control plane logging (audit), AKS diagnostic settings (kube-audit), GKE Cloud Audit Logs. Self-managed: API server --audit-policy-file."],
    ["Identify the suspicious workload or principal", "Alerts from Falco / runtime security, GuardDuty EKS findings, Defender for Containers; note namespace, pod, service account, node."],
    ["Snapshot evidence before deleting pods", "kubectl get pod -o yaml, kubectl logs (and --previous), describe; node disk snapshot; container filesystem export (crictl / docker export) if possible."],
    ["Check for dangerous pod specs", "privileged: true, hostPID, hostNetwork, hostPath mounts (/, /var/run/docker.sock, /var/run/containerd), added capabilities like SYS_ADMIN — these allow node escape."],
    ["Review API activity in the audit log", "pods/exec and pods/attach, secrets get/list, create of clusterrolebindings (especially to cluster-admin), new serviceaccounts and tokens, daemonsets and cronjobs."],
    ["Check for anonymous or exposed access", "Requests by system:anonymous, exposed kubelet (10250), dashboards, or API server reachable from the internet."],
    ["Review RBAC for over-privilege", "kubectl auth can-i --list --as=system:serviceaccount:<ns>:<sa>; look for wildcards and cluster-admin bindings."],
    ["Inspect images and running processes", "Image digests vs your registry, unknown registries, crypto-miner processes, outbound connections to mining pools. Scan images with Trivy."],
    ["Check the cloud layer", "Node instance roles and IRSA / workload identity: what cloud permissions were reachable from the compromised pods (IMDS access)."],
    ["Contain", "Apply a deny-all NetworkPolicy to the namespace, cordon and drain affected nodes, remove malicious bindings, rotate service-account tokens and secrets."],
    ["Rebuild affected nodes and redeploy from trusted images", "Do not trust nodes where privileged pods ran."],
    ["Harden and verify", "Pod Security Admission (restricted), kube-bench against CIS, private API endpoint, image signing / admission policy."]]},

  {id:"pb-exposed-bucket", name:"Exposed storage bucket", cat:"cloud", icon:"archive", level:"core", time:"1–3 h",
   desc:"Close a publicly exposed S3 bucket, Azure container or GCS bucket and establish whether anyone accessed the data.", steps:[
    ["Confirm the exposure and record evidence", "Unauthenticated listing/read test, how it was reported (researcher, tool such as GrayhatWarfare), screenshot and timestamp."],
    ["Block public access immediately", "S3 Block Public Access (bucket and account), remove public ACL / policy; Azure: disable anonymous blob access; GCS: remove allUsers / allAuthenticatedUsers, enable public access prevention."],
    ["Determine when it became public and who changed it", "CloudTrail PutBucketPolicy, PutBucketAcl, DeletePublicAccessBlock; Azure Activity Log; GCS Admin Activity audit logs."],
    ["Check what access logging exists", "S3 server access logs or CloudTrail data events, Azure StorageBlobLogs via diagnostic settings, GCS Data Access logs. If none were enabled, access cannot be ruled out."],
    ["Analyse access logs for anonymous and unknown access", "Requester '-' / anonymous, unknown IPs, ListObjects/GetObject volume, scanners and crawlers."],
    ["Inventory and classify the exposed data", "Personal data, credentials, keys, backups, source code. Secrets found must be rotated."],
    ["Rotate any credentials found in the bucket", "Config files, .env, database dumps, SSH keys."],
    ["Assess notification obligations", "Involve privacy/legal: personal data exposure may require regulator notification (e.g. 72 h under GDPR) even without proof of access."],
    ["Respond to the reporter if applicable", "Thank them, confirm closure; check your vulnerability disclosure policy."],
    ["Prevent recurrence", "Account-level public access block, SCP or Azure Policy denying public access, IaC scanning in Cloud → Misconfig scanner."]]},
  /* ------------------------------------------------------------ FORENSICS */
  {id:"pb-memory-vol3", name:"Windows memory analysis (Volatility 3)", cat:"forensics", icon:"cpu", level:"advanced", time:"2–6 h",
   desc:"Find malicious processes, injection, network activity and persistence in a Windows memory image.", steps:[
    ["Record the image's source, acquisition tool and SHA-256", "WinPmem, Magnet RAM Capture, DumpIt or EDR memory capture; note system time at capture and time zone."],
    ["Identify the OS build and confirm symbols load", "vol -f mem.raw windows.info. Symbol download failures are the usual cause of empty plugin output."],
    ["List processes and their tree", "windows.pslist, windows.pstree; compare with windows.psscan to find unlinked or exited processes. Wrong parents (e.g. svchost.exe not under services.exe) stand out."],
    ["Review command lines", "windows.cmdline — encoded PowerShell, LOLBins with URLs, processes running from Temp, AppData or ProgramData. Decode with Decoder."],
    ["Review network connections", "windows.netscan (or windows.netstat on newer builds): owning PID, remote IPs and ports; send IPs to Capture."],
    ["Look for code injection", "windows.malfind for RWX private memory with PE headers or shellcode; windows.ldrmodules for unlinked DLLs; windows.hollowprocesses where available. Expect false positives from JIT runtimes."],
    ["Check loaded DLLs and handles of suspicious processes", "windows.dlllist --pid, windows.handles --pid (mutexes and files give malware family hints)."],
    ["Check services and persistence in memory", "windows.svcscan for unusual service binaries; windows.registry.printkey for Run keys; windows.registry.hivelist to locate hives."],
    ["Scan with YARA", "windows.vadyarascan (per process) or yarascan.YaraScan with your rules or community sets."],
    ["Dump suspicious processes and files for analysis", "windows.dumpfiles --pid or --virtaddr; windows.pslist --pid <n> --dump. Hash and run through the Malware sample triage playbook."],
    ["Check for credential access", "lsass.exe handles from unusual processes, dumped lsass files on disk; windows.hashdump only if in scope."],
    ["Correlate with disk and log timelines", "Process create times against Prefetch, 4688 and EDR. Send findings to the case timeline."]]},

  {id:"pb-win-timeline", name:"Windows disk timeline", cat:"forensics", icon:"history", level:"advanced", time:"4 h–2 days",
   desc:"Build a super-timeline from NTFS and execution artefacts to show what ran, what changed and who did it.", steps:[
    ["Work from a verified image or triage collection", "E01 / raw image with matching hashes, or KAPE output; mount read-only (Arsenal Image Mounter, FTK Imager)."],
    ["Parse the MFT and USN journal", "MFTECmd on $MFT and $J. Compare $STANDARD_INFORMATION and $FILE_NAME times — SI earlier than FN suggests timestomping."],
    ["Parse Prefetch", "PECmd: last 8 run times, run count and files referenced. Prefetch may be disabled on servers and some SSD systems."],
    ["Parse Amcache and ShimCache", "AmcacheParser (SHA-1 of executables, first-seen); AppCompatCacheParser (ShimCache shows presence, not proof of execution on Windows 10+)."],
    ["Parse LNK files and jump lists", "LECmd and JLECmd: files and folders opened, original paths, volume serials and network shares."],
    ["Parse ShellBags and user registry hives", "SBECmd for folder access; RECmd with batch files for UserAssist, RecentDocs, TypedPaths, RunMRU, MountPoints2."],
    ["Parse SRUM", "SrumECmd on SRUDB.dat (with the SOFTWARE hive): per-app network bytes sent/received over ~30 days — useful for exfiltration."],
    ["Parse event logs", "EvtxECmd or Hayabusa csv-timeline; logons, services, tasks, PowerShell 4104."],
    ["Check BAM, services and scheduled tasks", "SYSTEM hive BAM entries (last execution per user), Services key, C:\\Windows\\System32\\Tasks XML."],
    ["Check the Recycle Bin and volume shadow copies", "RBCmd on $I files; older versions of files and logs may survive in VSCs."],
    ["Merge into a single timeline and filter to the window of interest", "Timeline Explorer or a combined CSV; normalise everything to UTC."],
    ["Write the narrative: execution, persistence, access, exfiltration", "Each statement cites the artefact and its limitations."]]},

  {id:"pb-linux-host", name:"Linux host compromise", cat:"forensics", icon:"terminal", level:"advanced", time:"2–8 h",
   desc:"Triage a suspected compromised Linux server: logins, persistence, rogue processes and tampering.", steps:[
    ["Capture volatile data first", "Memory with AVML or LiME; then a collection with UAC (Unix-like Artifacts Collector). Use trusted static binaries if the system may be rootkitted."],
    ["Review running processes and network connections", "ps auxf, ss -tunap; look for processes from /tmp, /dev/shm, /var/tmp, deleted binaries (ls -l /proc/*/exe | grep deleted) and miners."],
    ["Review authentication logs", "/var/log/auth.log or /var/log/secure, journalctl -u ssh (or sshd); last, lastb, lastlog (wtmp/btmp). Successful logins from new IPs and brute-force followed by success."],
    ["Check SSH persistence", "authorized_keys for all users and root, sshd_config changes (AuthorizedKeysFile, PermitRootLogin)."],
    ["Check cron, systemd and init persistence", "/etc/crontab, /etc/cron.*, /var/spool/cron/*, systemd units in /etc/systemd/system and ~/.config/systemd/user, rc.local, systemd timers."],
    ["Check for library and shell hijacks", "/etc/ld.so.preload, LD_PRELOAD in environment files, .bashrc / .profile / /etc/profile.d additions, PAM module changes in /etc/pam.d."],
    ["Check for new users and sudo changes", "/etc/passwd (UID 0 accounts), /etc/shadow changes, /etc/sudoers and /etc/sudoers.d."],
    ["Verify package file integrity", "debsums -c (Debian/Ubuntu) or rpm -Va (RHEL); modified system binaries like ps, ss, ls, sshd are a rootkit sign."],
    ["Build a file timeline around the incident", "find / -xdev -newermt '<start>' ! -newermt '<end>' -type f; check shell histories (~/.bash_history) — often cleared or symlinked to /dev/null."],
    ["Review auditd and application logs", "ausearch -ts <time>; web server and application logs for the initial access."],
    ["Hash and analyse suspicious binaries", "sha256sum, file, strings; reputation lookup; Malware sample triage playbook."],
    ["Decide: rebuild rather than clean for root-level compromise", "Rotate keys and credentials stored on the host."]]},

  {id:"pb-macos-triage", name:"macOS triage", cat:"forensics", icon:"command", level:"advanced", time:"2–6 h",
   desc:"Collect and review the key macOS artefacts for persistence, execution and downloads on a suspect Mac.", steps:[
    ["Collect with a triage tool and record hashes", "Aftermath (Jamf) or UAC; mac_apt for parsing an image. The collector needs Full Disk Access to read protected data."],
    ["Review persistence locations", "LaunchAgents (~/Library and /Library), LaunchDaemons (/Library), login items and background items (sfltool dumpbtm on Ventura and later), cron, periodic scripts. KnockKnock lists them."],
    ["Check code signing of persistent and suspicious binaries", "codesign -dvv <path> and spctl -a -vv <path>; unsigned or ad-hoc signed items in persistence are a priority."],
    ["Review the unified log for the time window", "log show --start '<time>' --end '<time>' --predicate '...' (or collect a .logarchive). Look at process launches, Gatekeeper and XProtect activity, authentication."],
    ["Review download and quarantine history", "QuarantineEventsV2 database (com.apple.LaunchServices.QuarantineEventsV2) shows files downloaded and their source URLs; open it in the SQLite viewer."],
    ["Review TCC permissions", "TCC.db (user and system): which apps were granted Full Disk Access, screen recording, accessibility, camera, microphone."],
    ["Review browser history and shell history", "Safari History.db, Chrome History; ~/.zsh_history, ~/.bash_sessions."],
    ["Check configuration and MDM profiles", "System Settings → Profiles or profiles list / profiles show; unexpected profiles can install root certs or proxies."],
    ["Check network connections and running processes", "lsof -i, ps aux; unknown helpers in ~/Library/Application Support."],
    ["Check file system events for the window", "FSEvents (parsed with mac_apt or FSEventsParser) show file creation and deletion."],
    ["Record findings and decide on remediation", "Remove persistence, rotate keychain-stored credentials if compromised, reinstall if needed."]]},

  {id:"pb-mobile-triage", name:"Mobile device triage (iOS / Android)", cat:"forensics", icon:"phone", level:"advanced", time:"2–8 h",
   desc:"Lawfully preserve and examine a phone for evidence, spyware or stalkerware indicators.", steps:[
    ["Confirm authority and consent to examine the device", "Owner consent in writing or legal authority; scope the data categories you will examine."],
    ["Preserve the device state", "Record make, model, OS, lock state (BFU/AFU). Isolate from networks (Faraday bag or airplane mode) to prevent remote wipe — keep it charged."],
    ["If spyware or stalkerware is suspected, consider safety first", "Removing stalkerware can alert the abuser. Involve a support organisation and plan with the person before changing anything."],
    ["iOS: create an encrypted backup or sysdiagnose", "Finder / iTunes encrypted backup includes more data (keychain, Health); sysdiagnose captures logs useful for spyware checks."],
    ["iOS: scan with Mobile Verification Toolkit", "MVT (mvt-ios check-backup / check-fs) with current STIX2 indicator files from Amnesty Tech and others."],
    ["Android: collect with androidqf or ADB", "androidqf gathers packages, settings, logs and a backup for MVT (mvt-android check-androidqf); adb bugreport for logs."],
    ["Android: review installed apps and their permissions", "Accessibility services, device admin apps, notification listeners, sideloaded APKs (installer not Play Store) — common stalkerware traits."],
    ["Check configuration and MDM profiles and VPNs", "Unexpected profiles, root certificates or always-on VPNs can intercept traffic."],
    ["Parse artefacts with iLEAPP / ALEAPP", "Messages, call logs, locations, app usage; open app databases (sms.db, msgstore.db) in the SQLite viewer."],
    ["Use commercial extraction only where authorised and documented", "Full file-system extraction tools (e.g. Cellebrite, GrayKey) require legal authority and trained operators."],
    ["Document findings with confidence and safety recommendations", "Indicator matches, apps found, and next steps for the person (account security, device replacement)."]]},

  {id:"pb-acquisition-coc", name:"Evidence acquisition & chain of custody", cat:"forensics", icon:"stamp", level:"core", time:"1–4 h",
   desc:"Acquire digital evidence in order of volatility and keep a custody trail that will stand up to scrutiny.", steps:[
    ["Confirm authority and scope before touching anything", "Written authorisation, systems in scope, legal constraints (privacy, cross-border data)."],
    ["Photograph and document the scene and devices", "Screen state, connected cables and peripherals, serial numbers, system time versus a reference clock."],
    ["Collect in order of volatility", "RFC 3227: memory and network state first, then temporary files, disk, remote logs, backups."],
    ["Capture memory on live systems", "WinPmem / Magnet RAM Capture (Windows), AVML or LiME (Linux); write to external media, not the evidence disk."],
    ["Secure encryption keys before shutdown", "BitLocker: manage-bde -protectors -get C: or the recovery key from AD / Entra; FileVault recovery key; note logged-in sessions."],
    ["Image disks with a write blocker", "Hardware write blocker plus FTK Imager, Guymager or ewfacquire to E01; dd / dcfldd for raw. Cloud: snapshot volumes (e.g. EBS snapshot) and copy to a forensic account."],
    ["Hash at acquisition and verify the copy", "SHA-256 (and MD5 if required by policy) of source and image; record both and the tool versions."],
    ["Collect logs from remote sources", "SIEM exports, cloud audit logs, email gateway logs; hash each export."],
    ["Start and maintain the chain of custody record", "Item, description, hash, who collected, when, where stored, every transfer with signatures. OSINTrix's signed custody file helps."],
    ["Store evidence securely", "Sealed evidence bags with labels for physical items; access-controlled, logged storage for images. Work only on copies."],
    ["Record any deviation from procedure and why", "Honest notes protect admissibility better than a perfect-looking log."]]},

  /* ---------------------------------------------------------------- FRAUD */
  {id:"pb-invoice-fraud", name:"Invoice / payment fraud", cat:"fraud", icon:"scroll-text", level:"core", time:"1–4 h",
   desc:"Respond to a payment sent to a fraudster's account after fake or altered invoice details.", steps:[
    ["Call your bank's fraud team and request a recall immediately", "Give amount, date, beneficiary account and reference. Recalls succeed far more often within 24–48 h."],
    ["Report to law enforcement", "US: FBI IC3 (its Recovery Asset Team works with banks on recent wires). UK: Action Fraud / Report Fraud. Keep the reference number."],
    ["Verify with the genuine supplier by phone using a number on file", "Never use contact details from the suspicious invoice or email."],
    ["Preserve the invoice, emails and headers", ".eml with headers, PDF invoice and its metadata (exiftool / File inspector — author, creator tool, edit dates)."],
    ["Determine how the details were changed", "Look-alike domain, compromised supplier mailbox, compromised internal mailbox, or altered PDF. Hand off to the BEC playbook if a mailbox is involved."],
    ["Check vendor master-data changes in the ERP", "Who changed the bank details, when, and on what evidence."],
    ["Identify other payments at risk", "Pending payments to the same supplier, other suppliers with recent bank-detail changes."],
    ["Record the beneficiary account details as indicators", "IBAN / account / sort code, bank name, beneficiary name; share with your bank and industry fraud-sharing schemes where they exist."],
    ["Notify the supplier if they appear compromised", "They may have sent the same fake details to other customers."],
    ["Strengthen controls", "Mandatory call-back for bank-detail changes, dual approval, confirmation-of-payee checks where available, staff awareness."]]},

  {id:"pb-consumer-ato", name:"Account takeover in a consumer app", cat:"fraud", icon:"log-in", level:"core", time:"1–3 h",
   desc:"Confirm and reverse takeover of a customer account, find the method, and find other victims of the same campaign.", steps:[
    ["Lock the account and stop pending payouts or orders", "Freeze withdrawals, gift card redemptions and shipping changes while you investigate."],
    ["Reconstruct the session history", "Logins, devices, IPs, user agents, password reset and email/phone/MFA change events around the takeover time."],
    ["Identify the takeover method", "Credential stuffing (many accounts, same IP ranges), phishing (login right after a phishing campaign), SIM swap (SMS OTP after carrier change), infostealer cookies (session used without login), support social engineering."],
    ["Restore the legitimate owner", "Verify identity through a channel the attacker did not change; revert email, phone and MFA; revoke all sessions and tokens."],
    ["Reverse or dispute fraudulent transactions", "Refunds, chargeback handling, loyalty points restoration; record amounts."],
    ["Find linked victims", "Pivot on attacker device fingerprints, IPs, payout destinations, shipping addresses and new email domains across other accounts."],
    ["Check for data the attacker accessed", "Saved cards (masked), addresses, messages — may trigger notification duties."],
    ["Block attacker indicators", "Device IDs, payout accounts, addresses; rate limits for the IP ranges used."],
    ["Communicate with the customer", "What happened, what you reversed, and advice (unique password, app-based MFA, check email account security)."],
    ["Add detection and friction for the pattern", "Step-up authentication for new devices and for changes to email, phone, MFA and payout methods; alerts for multiple accounts sharing a device."]]},

  {id:"pb-scam-takedown", name:"Scam website takedown", cat:"fraud", icon:"flag", level:"core", time:"1–2 h",
   desc:"Document a scam or phishing site and get it blocked and taken down through the right abuse channels.", steps:[
    ["Capture evidence before reporting", "urlscan.io scan, Wayback Machine Save Page Now, screenshots with URL and time, page source. Sites vanish or cloak after reports."],
    ["Extract indicators from the page", "Domains, IPs, payment details, wallets, phone numbers, emails — paste into Capture."],
    ["Identify the registrar, host and CDN", "RDAP for registrar and abuse contact; IP → ASN for the hosting provider; Cloudflare-fronted sites go via Cloudflare's abuse form, which forwards to the host."],
    ["Report to browser blocklists", "Google Safe Browsing report form, Microsoft 'Report an unsafe site' (SmartScreen), Netcraft report. Blocklisting protects users fastest."],
    ["Report to the registrar and hosting provider", "Use their abuse contact; include evidence, the impersonated brand and why it is fraudulent. Keep reports short and factual."],
    ["Report to phishing clearing houses", "APWG (reportphishing@apwg.org), PhishTank; national CERT or e.g. UK NCSC Suspicious Email Reporting Service for phishing emails."],
    ["Report linked payment and advertising channels", "Payment processors, crypto exchanges for deposit addresses, and the ad platform if the scam was promoted with ads."],
    ["Track each report and its outcome", "Date sent, ticket number, response; escalate if no action in 48–72 h."],
    ["Monitor for re-emergence", "Same kit or content on new domains: urlscan saved searches, crt.sh, dnstwist."],
    ["Warn affected users or customers if needed", "Publish a notice listing known fake domains; tell users what you will never ask for."]]},
];
